// Copies the photo rules into the folder the Edge Function can import from.
// Run after editing packages/decision/src/photo.ts:   node scripts/sync-shared.cjs
const fs = require('fs');
const path = require('path');

const src = path.join('packages', 'decision', 'src', 'photo.ts');
const dst = path.join('supabase', 'functions', '_shared', 'photo.ts');
const header =
  '// GENERATED by scripts/sync-shared.cjs from packages/decision/src/photo.ts.\n' +
  '// Do not edit this copy. Edit the original and run the script again.\n';

const body = fs.readFileSync(src, 'utf8').replace(/\r\n/g, '\n');
fs.mkdirSync(path.dirname(dst), { recursive: true });
fs.writeFileSync(dst, header + body);
console.log('Wrote ' + dst);